effect.shader:
const float PI = 3.14159265359;

/** O mapa naquele ponto, 0 (longe) a 1 (perto). */
float lerMapa(vec2 uv) {
    float v = dot(texture(depthMap, uv).rgb, vec3(0.299, 0.587, 0.114));
    return invertDepth ? 1.0 - v : v;
}

// ------------------------------------------------ a superfície reconstruída

ivec2 tamanhoCheio() {
    return textureSize(dispBuf, 0);
}

/** A disparidade refinada (passe 0), desempacotada. Sempre por texel inteiro. */
float disparidadeEm(ivec2 p) {
    ivec2 t = tamanhoCheio();
    vec4 v = texelFetch(dispBuf, clamp(p, ivec2(0), t - 1), 0);
    return v.r + v.g / 255.0;
}

/** Disparidade -> distância. Ver o cabeçalho. */
float distanciaEm(ivec2 p) {
    float r = max(sceneDepth, 1.0001);
    return 1.0 / (1.0 / r + disparidadeEm(p) * (1.0 - 1.0 / r));
}

float tangenteDoCampo() {
    return tan(radians(clamp(fieldOfView, 1.0, 170.0)) * 0.5);
}

/** O ponto 3D atrás do pixel p. Câmera na origem, olhando para +z. */
vec3 posicaoEm(ivec2 p) {
    vec2 t = vec2(tamanhoCheio());
    vec2 uv = (vec2(p) + 0.5) / t;
    float z = distanciaEm(p);
    float th = tangenteDoCampo();
    return vec3((uv.x * 2.0 - 1.0) * z * th * (t.x / t.y), (uv.y * 2.0 - 1.0) * z * th, z);
}

/** Onde, na tela (0..1), cai um ponto 3D. */
vec2 projetar(vec3 q) {
    vec2 t = vec2(tamanhoCheio());
    float th = tangenteDoCampo();
    return vec2(q.x / (q.z * th * (t.x / t.y)), q.y / (q.z * th)) * 0.5 + 0.5;
}

ivec2 texelCheio(vec2 uv) {
    return ivec2(uv * vec2(tamanhoCheio()));
}

/**
 * A normal por diferença de UM LADO só em cada eixo — o lado de menor salto de
 * profundidade. A diferença central atravessa dois objetos na borda e entorta a
 * normal: é daí que vem o contorno escuro.
 */
vec3 normalEm(ivec2 p) {
    vec3 c = posicaoEm(p);
    vec3 xm = posicaoEm(p - ivec2(1, 0));
    vec3 xp = posicaoEm(p + ivec2(1, 0));
    vec3 ym = posicaoEm(p - ivec2(0, 1));
    vec3 yp = posicaoEm(p + ivec2(0, 1));
    vec3 dx = abs(xp.z - c.z) < abs(c.z - xm.z) ? xp - c : c - xm;
    vec3 dy = abs(yp.z - c.z) < abs(c.z - ym.z) ? yp - c : c - ym;
    vec3 n = normalize(cross(dx, dy));
    // Virada para a câmera (que está na origem).
    return dot(n, -c) < 0.0 ? -n : n;
}

/** O salto relativo de profundidade em volta de p: grande = borda de objeto. */
float saltoEm(ivec2 p) {
    float z = distanciaEm(p);
    float m = max(
        max(abs(distanciaEm(p + ivec2(1, 0)) - z), abs(distanciaEm(p - ivec2(1, 0)) - z)),
        max(abs(distanciaEm(p + ivec2(0, 1)) - z), abs(distanciaEm(p - ivec2(0, 1)) - z))
    );
    return m / max(z, 1e-4);
}

// --------------------------------------------------------------- o estimador

float bayer4(ivec2 p) {
    int i = (p.y & 3) * 4 + (p.x & 3);
    const float M[16] = float[16](
         0.0,  8.0,  2.0, 10.0,
        12.0,  4.0, 14.0,  6.0,
         3.0, 11.0,  1.0,  9.0,
        15.0,  7.0, 13.0,  5.0
    );
    return (M[i] + 0.5) / 16.0;
}

/**
 * A amostra i de n do kernel, no hemisfério z >= 0, concentrada perto do
 * centro (escala de 0,1 a 1 pelo quadrado do índice). Espiral dourada com peso
 * de cosseno: determinística, sem tabela.
 */
vec3 amostraDoKernel(int i, int n, float semente) {
    float t = (float(i) + 0.5) / float(n);
    float fi = float(i) * 2.39996323 + semente;
    float cosT = sqrt(1.0 - t * 0.95);
    float sinT = sqrt(max(0.0, 1.0 - cosT * cosT));
    float escala = mix(0.1, 1.0, t * t);
    return vec3(cos(fi) * sinT, sin(fi) * sinT, cosT) * escala;
}

float pesoDaQueda(float t) {
    if (aoFalloff == 0) return 1.0 - 0.75 * t;
    if (aoFalloff == 2) return exp(-2.5 * t);
    return 1.0 - 0.75 * t * t * (3.0 - 2.0 * t);
}

float ocluir(vec3 P, mat3 tbn, float raio, int n, float semente) {
    float occ = 0.0;
    float total = 0.0;
    for (int i = 0; i < 32; i++) {
        if (i >= n) break;
        vec3 k = amostraDoKernel(i, n, semente);
        float peso = pesoDaQueda(clamp(length(k), 0.0, 1.0));
        total += peso;

        vec3 Q = P + tbn * k * raio;
        if (Q.z <= 0.0) continue;
        vec2 suv = projetar(Q);
        if (suv.x < 0.0 || suv.y < 0.0 || suv.x > 1.0 || suv.y > 1.0) continue;
        float zCena = distanciaEm(texelCheio(suv));

        // Alcance: cai com a distância entre o ponto e a superfície achada.
        float alcance = smoothstep(0.0, 1.0, raio / max(abs(P.z - zCena), 1e-4));
        // Bloqueada: a cena está NA FRENTE da amostra.
        occ += (zCena <= Q.z - aoBias ? 1.0 : 0.0) * alcance * peso;
    }
    return total > 0.0 ? occ / total : 0.0;
}

int amostrasDaQualidade() {
    if (aoQuality == 0) return 8;
    if (aoQuality == 2) return 16;
    if (aoQuality == 3) return 24;
    return 12;
}

int amostrasDeContato() {
    if (!contactAo || contactStrength <= 0.0 || aoQuality == 0) return 0;
    return aoQuality == 3 ? 8 : 4;
}

// ------------------------------------------------------------------ limpeza

float aoEm(sampler2D fonte, ivec2 q) {
    ivec2 t = textureSize(fonte, 0);
    return texelFetch(fonte, clamp(q, ivec2(0), t - 1), 0).r;
}

/** A distância na superfície embaixo do texel q de um buffer de meia resolução. */
float distanciaDoTexelReduzido(ivec2 q, ivec2 tamanhoReduzido) {
    vec2 uv = (vec2(q) + 0.5) / vec2(tamanhoReduzido);
    return distanciaEm(texelCheio(uv));
}

float limpar(sampler2D fonte, ivec2 direcao) {
    ivec2 t = textureSize(fonte, 0);
    ivec2 q0 = ivec2(acScreenNorm * vec2(t));
    float z0 = distanciaDoTexelReduzido(q0, t);
    float tolerancia = max(aoRadius * 0.5, z0 * 0.02);
    float soma = 0.0;
    float peso = 0.0;
    // 4 texels: a largura exata do ruído 4×4.
    for (int i = -2; i < 2; i++) {
        ivec2 q = q0 + direcao * i;
        float z = distanciaDoTexelReduzido(q, t);
        float w = exp(-abs(z - z0) / tolerancia);
        soma += aoEm(fonte, q) * w;
        peso += w;
    }
    return peso > 1e-4 ? soma / peso : aoEm(fonte, q0);
}

/** A ampliação ao tamanho cheio, pesando os 4 texels reduzidos pela profundidade. */
float ampliar(sampler2D fonte) {
    ivec2 t = textureSize(fonte, 0);
    vec2 base = acScreenNorm * vec2(t) - 0.5;
    ivec2 q0 = ivec2(floor(base));
    vec2 f = fract(base);
    float z0 = distanciaEm(texelCheio(acScreenNorm));
    float tolerancia = max(aoRadius * 0.25, z0 * 0.01);
    float soma = 0.0;
    float peso = 0.0;
    for (int j = 0; j < 2; j++) {
        for (int i = 0; i < 2; i++) {
            ivec2 q = q0 + ivec2(i, j);
            float bi = (i == 0 ? 1.0 - f.x : f.x) * (j == 0 ? 1.0 - f.y : f.y);
            float w = (bi + 1e-3) * exp(-abs(distanciaDoTexelReduzido(q, t) - z0) / tolerancia);
            soma += aoEm(fonte, q) * w;
            peso += w;
        }
    }
    return peso > 1e-5 ? soma / peso : aoEm(fonte, q0);
}

// --------------------------------------------------------------------- main

void main() {
    // 0. A reconstrução: o mapa guiado pela cor, empacotado em 16 bits.
    if (acPass == 0) {
        vec3 c0 = texture(inputImg, acScreenNorm).rgb;
        float soma = 0.0;
        float peso = 0.0;
        for (int j = -2; j <= 2; j++) {
            for (int i = -2; i <= 2; i++) {
                vec2 uv = acScreenNorm + vec2(float(i), float(j)) * 2.0 * acTexelSize;
                vec3 c = texture(inputImg, uv).rgb - c0;
                float w = exp(-dot(c, c) * 40.0) * exp(-float(i * i + j * j) / 8.0);
                soma += lerMapa(uv) * w;
                peso += w;
            }
        }
        float d = clamp(soma / max(peso, 1e-5), 0.0, 1.0);
        float alto = floor(d * 255.0) / 255.0;
        fragColor = vec4(alto, fract(d * 255.0), 0.0, 1.0);
        return;
    }

    // 1. O AO, em meia resolução.
    if (acPass == 1) {
        ivec2 p = texelCheio(acScreenNorm);
        vec3 P = posicaoEm(p);
        vec3 n = normalEm(p);
        float ang = bayer4(ivec2(gl_FragCoord.xy)) * 2.0 * PI;
        vec3 giro = vec3(cos(ang), sin(ang), 0.0);
        vec3 t = giro - n * dot(giro, n);
        if (dot(t, t) < 1e-4) {
            giro = vec3(0.0, cos(ang), sin(ang));
            t = giro - n * dot(giro, n);
        }
        t = normalize(t);
        mat3 tbn = mat3(t, cross(n, t), n);

        float ao = 1.0 - ocluir(P, tbn, aoRadius, amostrasDaQualidade(), 0.0);
        int nContato = amostrasDeContato();
        if (nContato > 0) {
            float contato = 1.0 - ocluir(P, tbn, aoRadius * 0.125, nContato, 1.3);
            ao = min(ao, mix(1.0, contato, contactStrength));
        }

        // Confiança: perto de borda de objeto e onde o alfa é baixo, menos AO.
        float borda = smoothstep(0.08, 0.25, saltoEm(p));
        float alfa = smoothstep(0.0, 0.5, texture(inputImg, acScreenNorm).a);
        ao = mix(1.0, ao, (1.0 - borda) * alfa);
        fragColor = vec4(ao, ao, ao, 1.0);
        return;
    }

    // 2. e 3. A limpeza separável.
    if (acPass == 2) {
        float v = limpar(aoRaw, ivec2(1, 0));
        fragColor = vec4(v, v, v, 1.0);
        return;
    }
    if (acPass == 3) {
        float v = limpar(aoBlurH, ivec2(0, 1));
        fragColor = vec4(v, v, v, 1.0);
        return;
    }

    // 4. Aplicar.
    vec4 src = texture(inputImg, acScreenNorm);
    ivec2 p = texelCheio(acScreenNorm);

    if (aoView == 1) {
        fragColor = vec4(vec3(disparidadeEm(p)), src.a);
        return;
    }
    if (aoView == 2) {
        fragColor = vec4(normalEm(p) * 0.5 + 0.5, src.a);
        return;
    }
    if (aoView == 3) {
        fragColor = vec4(vec3(texture(aoRaw, acScreenNorm).r), src.a);
        return;
    }

    float ao = ampliar(aoBlurV);
    if (aoView == 4) {
        fragColor = vec4(vec3(ao), src.a);
        return;
    }

    ao = pow(clamp(ao, 0.0, 1.0), aoContrast);
    float escurecer = clamp((1.0 - ao) * aoIntensity, 0.0, 1.0);

    if (aoView == 5) {
        fragColor = vec4(vec3(escurecer), src.a);
        return;
    }

    // "Só o AO": em cinza, para compor com Multiplicar — o jeito de quem vem do
    // After Effects. Opaco onde a camada existe.
    if (aoOutput == 1) {
        fragColor = vec4(vec3(1.0 - escurecer), src.a);
        return;
    }

    // Só o RGB: alfa direto, intacto.
    vec3 cor = mix(vec3(1.0), aoColor.rgb, escurecer * aoColor.a);
    fragColor = vec4(src.rgb * cor, src.a);
}
